import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 38 · Christmas recipe: the holiday cheese ball (Google Trends 3/11: christmas appetizer recipes, christmas snacks rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, in nineteen sixty-eight, there wasn't a Christmas party in America without a cheese ball on the table. Round as a snowball, rolled in chopped pecans, sitting on a plate of crackers with a little knife stuck in the top. People stood around it all night. The cheese ball was where all the gossip happened.""",
   "cheese ball pecans crackers platter", "WHERE THE GOSSIP HAPPENED")
sc("""But today, people tell me theirs tastes like plain cream cheese, or it melts into a puddle, or the nuts fall off. So tonight I'm giving you my Christmas cheese ball, every step, and the four mistakes that make it bland and sloppy. And stay with me, because the last trick is how to make it look like a Christmas present on the table.""",
   "homemade cheese ball Christmas table", "BLAND AND SLOPPY")

ch("The party food of the sixties")
sc("""The cheese ball came into fashion in the fifties and sixties, when cream cheese was new and exciting and every hostess wanted something she could make the day before. Women's magazines printed a new cheese ball every December. Port wine cheese balls, bacon cheese balls, pineapple cheese balls. My mother tried every one, and my father ate every one.""",
   "1960s cocktail party hostess food", "A NEW ONE EVERY DECEMBER")
sc("""Mine came from my neighbor Betty Hartman, in nineteen sixty-six. She brought it to the church Christmas party, and people kept going back to it until the plate was licked clean. I followed her into the kitchen and asked for the recipe. She made me promise never to tell. Betty passed in two thousand nine, honey, so I think it's alright now.""",
   "church Christmas party 1960s table", "I PROMISED NEVER TO TELL")
sc("""And Betty's secret wasn't one thing. It was three. In a minute I'll tell you all three, and they're the reason her cheese ball tasted like something, and everybody else's tasted like a block of cream cheese with nuts on it.""",
   "woman smiling holding platter vintage", "THREE SECRETS")

sc("""My mother's favorite was a port wine cheese ball, pink as a ballerina's slipper, from a recipe on the back of a cheese box. My father called it the strawberry cheese, and he wouldn't touch it for three years. Then one Christmas he tried it by mistake in the dark, thinking it was fudge, and from then on he ate half of it every year.""",
   "pink port wine cheese spread", "THE STRAWBERRY CHEESE")

ch("What you need")
sc("""Here's what you need, honey. Two packages of cream cheese, eight ounces each, softened. Two cups of sharp cheddar cheese, shredded. Half a stick of butter, softened. Two green onions, sliced thin. One tablespoon of Worcestershire sauce. Half a teaspoon of garlic powder. A pinch of cayenne. And one cup of pecans, chopped fine, for the outside.""",
   "cream cheese cheddar green onions", "THE INGREDIENTS")
sc("""And now Betty's first secret. Sharp cheddar, the sharpest you can find, and shred it yourself from a block. That's mistake number one, using mild cheese or the bagged kind. Mild cheddar disappears into the cream cheese. And the bagged shredded cheese has a powder on it, so it won't stick together, and it makes the ball dry and grainy.""",
   "shredding sharp cheddar block grater", "SHRED IT YOURSELF")

ch("Mixing")
sc("""Step one. Make sure the cream cheese and butter are really soft. Leave them on the counter for an hour. Cold cream cheese makes lumps, and you'll never get them out. Put them in a big bowl and beat them together until they're smooth and fluffy, about two minutes. Then add the cheddar, the green onions, and everything else.""",
   "beating cream cheese mixer bowl", "REALLY SOFT")
sc("""And here's Betty's second secret. Worcestershire sauce and a little bit of cayenne. That's what gives it that deep, savory taste that makes people go back for more. Mistake number two is a cheese ball with no seasoning. Taste the mixture with a cracker before you shape it. It should taste a little too strong, because the flavor goes flat when it's cold.""",
   "Worcestershire sauce bottle spoon", "TASTE IT WITH A CRACKER")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now mix it all together with a spoon, just until everything is even. Don't beat it after you add the cheddar, or the cheese turns to paste. You want to still see little bits of orange cheese and green onion in it.""",
   "cheese mixture bowl green onion", "LITTLE BITS OF ORANGE")

ch("Shaping")
sc("""Step two, shaping. Scrape the mixture onto a big piece of plastic wrap. Pull up the corners and twist them together, and press it into a ball through the plastic, so your hands stay clean. Then twist the top tight and put it in the icebox for at least four hours, or overnight. Betty always made hers the night before.""",
   "cheese ball wrapped plastic wrap", "THROUGH THE PLASTIC")
sc("""Mistake number three is rolling it in the nuts right away, while it's soft. The nuts sink in, the ball sags into a pancake, and the whole thing slumps on the plate by the middle of the party. Chill it first, so it's firm. Then roll it in the nuts right before the party, and the nuts stay crisp and stuck on.""",
   "slumped melted cheese ball plate", "CHILL IT FIRST")
sc("""So far, sharp cheddar from the block, soft cream cheese, Worcestershire and cayenne, a gentle mix, and chilling it overnight before the nuts. Now Betty's third secret. Toast the pecans. Spread them on a baking sheet and bake them at three fifty for six or seven minutes, until they smell like warm butter. Let them cool, and chop them fine.""",
   "toasting pecans baking sheet", "TOAST THE PECANS")
sc("""Raw pecans taste like cardboard next to toasted ones, sweetheart. Toasting brings out all the oil and the flavor. And that's mistake number four, raw nuts on the outside. Some people also add chopped fresh parsley to the pecans for a little green. Betty did, and it made the whole thing look like a Christmas wreath.""",
   "chopped toasted pecans parsley", "NOT CARDBOARD")

sc("""And if a ball is too much for your family, make a log instead. Shape it in the plastic wrap like a fat sausage, about two inches across, and chill it. Then roll it in the pecans and slice it into rounds, one round for each cracker. It's neater on a buffet, and people don't have to fight over the little knife.""",
   "cheese log sliced rounds crackers", "MAKE A LOG")

ch("A Christmas present")
sc("""Now the trick I promised you, how to make it look like a Christmas present. Roll the cold ball in the toasted pecans, pressing them on with your hands so they cover every bit. Put it in the middle of a big platter. Then lay a few sprigs of fresh rosemary around the bottom like a wreath, and scatter some fresh cranberries in between.""",
   "cheese ball rosemary cranberries platter", "LIKE A WREATH")
sc("""And for the top, a little bow. Cut a strip of red bell pepper, and tie it, or lay two strips in a cross over the top, like ribbon on a package. Stick a little sprig of rosemary in the middle. My grandchildren call it the cheese present, and they won't let anybody cut it until Grandpa takes a picture.""",
   "cheese ball red pepper ribbon top", "THE CHEESE PRESENT")
sc("""Serve it with a good variety of crackers, honey. Butter crackers, wheat crackers, and some little slices of toasted bread. Celery sticks and apple slices too, for the people watching their figure. Take it out of the icebox about twenty minutes before the party, so it's soft enough to spread, but still holds its round shape.""",
   "crackers apple slices cheese ball", "TWENTY MINUTES BEFORE")

sc("""And always put out two knives, honey, not one. Betty taught me that. With one knife, a line forms, and people get shy and walk away. With two knives on opposite sides of the platter, everybody can dig in at once. Small things like that are the difference between a party people talk about and a party people forget.""",
   "two spreading knives cheese platter", "ALWAYS TWO KNIVES")

ch("Christmas variations")
sc("""Once you know the method, you can make it a hundred ways. For a sweet one, leave out the onions and garlic and use powdered sugar, vanilla and mini chocolate chips, and roll it in crushed graham crackers. The children go wild for that one. Serve it with vanilla wafers and pretzels.""",
   "chocolate chip dessert cheese ball", "THE CHILDREN GO WILD")
sc("""Or make a cranberry pecan one, with dried cranberries and a spoon of honey mixed in. Or a bacon ranch one, with crumbled bacon and a packet of ranch seasoning. Or roll little cheese balls the size of a walnut and put a pretzel stick in each one. Those are cheese ball pops, and they're gone in ten minutes at every party.""",
   "mini cheese ball bites pretzel sticks", "CHEESE BALL POPS")

ch("Make ahead")
sc("""And here's why every busy hostess loved the cheese ball. You can make it three days ahead and keep it wrapped in the icebox. Or freeze it for a month, without the nuts. Thaw it overnight in the icebox, then roll it in the pecans the day of the party. I make two in early December, and freeze one for the surprise visitors.""",
   "wrapped cheese ball freezer", "THREE DAYS AHEAD")
sc("""And it's a lovely gift, sweetheart. Wrap a cheese ball in plastic, tuck it in a small basket with a box of crackers and a little spreading knife tied with a ribbon. My neighbor across the street gets one every year. She says it's the only present she doesn't have to find a place for, because it's gone by New Year's.""",
   "gift basket cheese ball crackers", "GONE BY NEW YEAR'S")

ch("Grandma's kitchen")
sc("""So one more time. Sharp cheddar, shredded from the block. Really soft cream cheese. Worcestershire and a little cayenne, and taste it. Mix it gently. Shape it in plastic wrap and chill it overnight. Toasted pecans, rolled on right before the party. And a rosemary wreath and a red pepper bow. That's Betty Hartman's cheese ball, and it's never bland.""",
   "cheese ball Christmas party table", "NEVER BLAND")
sc("""Tell me in the comments, sweetheart. Was there a cheese ball at your family's Christmas? What kind? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas living room party evening", "WHAT KIND WAS IT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma38", "The Christmas Cheese Ball EVERYONE's Grandma Made (Why Yours Is BLAND)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "The cheese ball as a mid-century American party appetizer, popularized in 1950s and 1960s magazines.",
      "Recipe as written by Grandma Ruth: 16 oz cream cheese, 2 cups sharp cheddar, 1/4 cup butter, 2 green onions, 1 tbsp Worcestershire sauce, 1/2 tsp garlic powder, cayenne; chilled 4 hours or overnight; rolled in 1 cup toasted chopped pecans."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
